- */
-%option noyyalloc
-%option noyyrealloc
-%option noyyfree
-
-%{
-	/*
-	 * dtd_preparse.l
-	 *
-	 * an XML dissector for wireshark
-	 *
-	 * DTD Preparser -  import a dtd file into a GString
-	 *		    including files, removing comments
