-
-%}
-xmlpi_start "<?"
-xmlpi_stop  "?>"
-xmlpi_chars .
-
-comment_start "<!--"
-comment_stop "-->"
-special_start "<!"
-special_stop ">"
-
-entity_start     "<!"[[:blank:]\n]*entity[[:blank:]\n]*"%"
-system     SYSTEM
-filename   [^"]+
-
-
-name [A-Za-z][-:A-Za-z0-9_\.]*
-
-quote "\""
-percent [%]
-escaped_quote "\\\""
-non_quote [^"%]+
-
-avoid_editor_bug ["]
-
-entity        [%&][A-Za-z][-A-Za-z0-9_]*;
-
-whitespace [[blank:]]+
