-
-
-{entity}				if (yyextra->current) g_string_append_printf(yyextra->current,"%s\n%s\n",replace_entity(yyextra, yytext),dtd_location(yyextra));
-
-{whitespace}				if (yyextra->current) g_string_append(yyextra->current," ");
